class LRUCache:
    """Least Recently Used cache backed by a dict and an insertion-order list."""

    def __init__(self, capacity: int):
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self.capacity = capacity
        self._store: dict[int, object] = {}       # key -> value
        self._order: list[int] = []                # keys ordered by recency (oldest first)

    def get(self, key: int) -> int:
        if key not in self._store:
            return -1
        # Move to most-recently-used position
        self._order.remove(key)
        self._order.append(key)
        return self._store[key]

    def put(self, key: int, value: object) -> None:
        if key in self._store:
            # Update value and mark as most-recently-used
            self._store[key] = value
            self._order.remove(key)
            self._order.append(key)
        else:
            if len(self._store) >= self.capacity:
                # Evict least-recently-used (first in _order)
                evicted = self._order.pop(0)
                del self._store[evicted]
            self._store[key] = value
            self._order.append(key)
